== resources/officefloor/rest/api/sheets/{sheetId}/claims/{claimId}/resettle.POST.yml
# POST /api/sheets/{sheetId}/claims/{claimId}/resettle — re-settle a SETTLED claim (body {user}): freeze
# it again at the due it would have today as an OPEN claim bound by no statement (today's rates, grades,
# floor and late charge), and log a SETTLED line for it. Only a steward re-settles a claim. Refused (400)
# when the user is not a steward, the claim is not SETTLED or not on the sheet, or its date falls in a
# closed period; nothing is stored then. A stored re-settle is recorded in the audit file as CLAIM_RESETTLED.
validate:
  class: net.officefloor.hq.app.claim.ValidateResettle
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: checkClaim
checkClaim:
  class: net.officefloor.hq.app.claim.CheckClaimPeriod
  govern: [ transaction ]
  next: checkResettle
checkResettle:
  class: net.officefloor.hq.app.claim.CheckResettle
  govern: [ transaction ]
  next: snapshot
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyResettle
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.AuditClaimResettled
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
== resources/officefloor/rest/api/sheets/{sheetId}/claims/{claimId}/status.POST.yml
# POST /api/sheets/{sheetId}/claims/{claimId}/status — move a claim to a new status (body
# {status, user, review, reason}): DRAFT to OPEN, OPEN to SETTLED, DRAFT, OPEN or PENDING to VOID.
# A clerk (any user not assigned steward) settling a claim whose due is above the sheet's clerk limit
# sends it to PENDING instead. A steward reviews a PENDING claim (review true): status SETTLED approves
# it (not by the user who opened it), status OPEN with a reason rejects it. Refused (400) for any
# other change, when the user who opened the claim tries to settle it, when the claim is not on
# the sheet, or when its date falls in a closed period; nothing is stored then. Opening records the
# user as the claim's opened-by. A stored change is recorded in the audit file as CLAIM_OPENED,
# CLAIM_PENDING, CLAIM_SETTLED, CLAIM_APPROVED, CLAIM_REJECTED or CLAIM_VOIDED.
validate:
  class: net.officefloor.hq.app.claim.ValidateStatus
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: checkClaim
checkClaim:
  class: net.officefloor.hq.app.claim.CheckClaimPeriod
  govern: [ transaction ]
  next: checkLimit
checkLimit:
  class: net.officefloor.hq.app.claim.CheckClerkLimit
  govern: [ transaction ]
  next: snapshot
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyStatus
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaim
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.AuditClaimStatus
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
== Claim
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A person's claim on a sheet. {@code amount} has two decimals and is 0.00 or more, or negative for
 *  a correction, which names the number of the settled claim of its person it corrects; it starts
 *  as {@link ClaimStatus#DRAFT}. */
public class Claim {
    private final long id;
    private final String sheetId;
    private long personId;
    private BigDecimal amount;
    private LocalDate date;
    private String note;
    private ClaimStatus status;
    private String number;
    private BigDecimal settledDue;
    private String openedBy;
    private boolean stated;
    private BigDecimal statedDue;
    private boolean statedNa;
    private String corrects;
    private final LocalDate dueBy;

    public Claim(long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
            ClaimStatus status, String number, BigDecimal settledDue, String openedBy, boolean stated,
            BigDecimal statedDue, String corrects, LocalDate dueBy) {
        this.id = id;
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.note = note;
        this.status = status;
        this.number = number;
        this.settledDue = settledDue;
        this.openedBy = openedBy;
        this.stated = stated;
        this.statedDue = statedDue;
        this.corrects = corrects;
        this.dueBy = dueBy;
    }

    public long getId() { return id; }
    public String getSheetId() { return sheetId; }
    public long getPersonId() { return personId; }
    public BigDecimal getAmount() { return amount; }
    public LocalDate getDate() { return date; }
    public String getNote() { return note; }
    public ClaimStatus getStatus() { return status; }
    /** The number given when the claim was opened (the sheet-wide 1, 2, ..., or <period>-<n> / X-<n>
     *  while the sheet numbers by period); null for a draft, or a claim voided as a draft;
