package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.time.LocalDate;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimFigure;
import net.officefloor.hq.app.claim.ClaimStore;
import net.officefloor.hq.app.claim.Lateness;
import net.officefloor.hq.app.claim.Rounding;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.RateStore;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.SheetStore;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Takes a statement of the person on the sheet's today: their due-total (the sum of the figures of
 *  their claims that count; n/a when their grade in force today has no rate today and no counting claim
 *  keeps a fixed figure or a figure at another grade, the one in force on its date), binding each counting claim to its figure now (its floored live due when not fixed) and unbinding the rest. A settled
 *  claim keeps its fixed figure. The due-total includes the late charges of overdue claims, but a
 *  claim is bound to its figure without its charge, which keeps following the sheet's today. The
 *  due-total is at most the sheet's cap. */
public class TakeStatement {
    public void take(@Val StatementRequest request, @Val Person person, ClaimStore claims, RateStore rates,
            SheetStore sheets, SettingStore settings, StatementStore statements, Out<Statement> statementOut) {
        String sheetId = person.getSheetId();
        LocalDate today = sheets.today(sheetId);
        Rounding rounding = Rounding.of(sheetId, settings, sheets, claims);
        Lateness lateness = new Lateness(settings.latePcts(sheetId), settings.floors(sheetId), today, rounding);
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean fixed = false;
        int counted = 0;
        // Locked, so a status change or another statement made at once waits for this one.
        for (Claim claim : claims.listForUpdate(sheetId, person.getId())) {
            // An OPEN (or PENDING) claim dated within a hold counts in no live total unless a statement bound
            // it, so a statement neither counts nor binds it; one it bound before stays counted.
            boolean counts = RollupService.counts(claim, person);
            BigDecimal figure = null;
            if (counts) {
                figure = ClaimFigure.of(claim, rates.find(sheetId, person.gradeOn(claim.getDate()), claim.getDate()), lateness.floor(claim), rounding);
                counted++;
                if (figure != null) {
                    total = total.add(claim.getSettledDue() != null ? figure : figure.add(lateness.charge(claim, figure)));
                }
                // A figure at a grade other than the one in force today, or at a rate that ended before
                // today, does not hang on today's grade's rate.
                fixed |= claim.getSettledDue() != null || (claim.isBound() && claim.getStatedDue() != null)
                        || (figure != null && (!person.gradeOn(claim.getDate()).equals(person.gradeOn(today))
                                || rates.endsBefore(sheetId, person.gradeOn(claim.getDate()), claim.getDate(), today)));
            }
            // A claim whose rate ended before its date is bound to n/a, so a later rate leaves it so.
            boolean na = counts && figure == null && (claim.isBound()
                    || (claim.getSettledDue() == null && rates.ended(sheetId, person.gradeOn(claim.getDate()), claim.getDate())));
            claim.setStated(counts);
            claim.setStatedDue(figure);
            claim.setStatedNa(na);
            claims.bind(claim);
        }
        boolean na = rates.find(sheetId, person.gradeOn(today), today) == null && !fixed;
        Statement statement = new Statement(person.getId(), today,
                na ? null : SettingStore.capped(total, settings.cap(sheetId)), counted);
        statements.add(sheetId, statement, request.user());
        statementOut.set(statement);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import net.officefloor.hq.app.period.PeriodStore;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.hq.app.rate.RateStore;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.SheetStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Moves the claim to the new status, refusing a change its current status does not allow. Opening
 *  gives the claim its next number (see {@link Numbering}) and records who opened it; a voided claim keeps its number, which is never reused. Settling fixes its due at its person's
 *  grade rate in force on the claim's date, rounded as the sheet's policy date has it and at least the sheet's floor (none when no rate of the grade applies then),
 *  or at the figure its person's last statement bound it to, plus the late charge it has then (frozen in).
 *  A clerk's settle above the clerk limit makes it PENDING instead (see {@link CheckClerkLimit}); a steward's
 *  approval settles a PENDING claim, frozen then at its live figure (a statement does not bind it while
 *  PENDING), and a rejection moves it back to OPEN, bound again by its person's last statement if that included it.
 *  The user who opened a claim may not settle or approve it. */
public class ApplyStatus {
    public void apply(@Val StatusInput input, @Val StatusMove move, @Val Claim claim, ClaimStore store, PersonStore people,
            RateStore rates, SettingStore settings, SheetStore sheets, PeriodStore periods,
            Out<StatusChange> change)
            throws InvalidSheetException {
        ClaimStatus from = move.from();
        ClaimStatus to = move.to();
        if (input.status() == ClaimStatus.SETTLED && claim.getOpenedBy() != null
                && claim.getOpenedBy().equals(input.user())) {
            throw new InvalidSheetException("The user who opened a claim cannot "
                    + (input.review() ? "approve" : "settle") + " it");
        }
        if (!from.canBecome(to) || !store.move(claim, from, to)) {
            throw new InvalidSheetException("A " + from + " claim cannot become " + to);
        }
        // The due to freeze is worked out while the claim is still OPEN or PENDING, so it takes its late charge in.
        BigDecimal settledDue = null;
        if (to == ClaimStatus.SETTLED) {
            Person person = people.find(claim.getSheetId(), claim.getPersonId());
            BigDecimal pct = person == null ? null : rates.find(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate());
            settledDue = Lateness.of(claim.getSheetId(), settings, sheets, store).due(claim, pct);
        }
        claim.setStatus(to);
        if (from == ClaimStatus.DRAFT && to == ClaimStatus.OPEN) {
            claim.setNumber(Numbering.next(claim.getSheetId(), claim.getDate(), store, settings, sheets, periods));
            claim.setOpenedBy(input.user());
        }
        if (to == ClaimStatus.SETTLED) {
            claim.setSettledDue(settledDue);
        }
        change.set(new StatusChange(claim.getNumber()));
    }
}
package net.officefloor.hq.app.claim;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.PeriodStore;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.hq.app.rate.RateStore;
import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.hq.app.sheet.SheetStore;
import net.officefloor.plugin.variable.Val;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

/** Settles each selected claim, in list order: its people in the order they were added, a person's
 *  claims newest first. Each goes through the very steps of a single settle by the user (period,
 *  clerk limit, opened-by and status checks, then store, log and audit), so a clerk's settle above
 *  the clerk limit sends it to PENDING, which counts as settled. A claim that is not on the sheet,
 *  or that a single settle would refuse, is refused and left as it is. */
public class SettleClaims {
    public void settle(@PathVariable("sheetId") String sheetId, @Val BulkSettleInput input, ClaimStore store,
            PersonStore people, PeriodStore periods, SettingStore settings, SheetStore sheets, RoleStore roles,
            RateStore rates, ClaimLogStore log, RollupService rollups, Audit audit, Out<BulkSettleResult> result) {
        String sheet = sheetId.trim();
        Map<Long, Integer> personOrder = new HashMap<>();
        for (Person person : people.list(sheet)) {
            personOrder.put(person.getId(), personOrder.size());
        }
        int refused = 0;
        List<Claim> selected = new ArrayList<>();
        for (Long id : input.claimIds()) {
            Claim claim = id == null ? null : store.find(sheet, id);
            if (claim == null) {
                refused++;
            } else {
                selected.add(claim);
            }
        }
        selected.sort(Comparator.<Claim>comparingInt(c -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE))
                .thenComparing(Comparator.comparingLong(Claim::getId).reversed()));
        StatusInput status = new StatusInput(ClaimStatus.SETTLED, input.user(), false, "");
        int settled = 0;
        for (Claim claim : selected) {
            try {
                new CheckClaimPeriod().check(claim, periods);
                StatusMove[] move = new StatusMove[1];
                new CheckClerkLimit().check(status, claim, roles, settings, people, rates, sheets, store, m -> move[0] = m);
                Rollup before = rollups.snapshot(sheet);
                StatusChange[] change = new StatusChange[1];
                new ApplyStatus().apply(status, move[0], claim, store, people, rates, settings, sheets, periods,
                        c -> change[0] = c);
                new SaveClaim().save(status, claim, store, log);
                new AuditClaimStatus().audit(status, move[0], claim, change[0], before, people, audit, rollups);
                settled++;
            } catch (InvalidSheetException e) {
                refused++;
            }
        }
        result.set(new BulkSettleResult(settled, refused));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.plugin.variable.Val;

/** Records a stored status change: CLAIM_OPENED, CLAIM_PENDING, CLAIM_SETTLED, CLAIM_APPROVED,
 *  CLAIM_REJECTED or CLAIM_VOIDED sheet=<id> by=<user> person=<name> amount=<0.00> date=<yyyy-mm-dd>,
 *  then number=<n> when the claim has or had a number, then for CLAIM_SETTLED and CLAIM_APPROVED
 *  due=<0.00> as fixed on settling (n/a when its grade had no rate), for CLAIM_REJECTED reason=<reason>. */
public class AuditClaimStatus {
    public void audit(@Val StatusInput input, @Val StatusMove move, @Val Claim claim, @Val StatusChange change, @Val Rollup before,
            PersonStore people, Audit audit, RollupService rollups) {
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        ClaimResponse shown = ClaimResponse.from(claim);
        audit.record(move.to().event(move.from()) + " sheet=" + claim.getSheetId() + " by=" + input.user() + " person="
                + person.getName() + " amount=" + shown.amount() + " date=" + shown.date()
                + (change.number() == null ? "" : " number=" + change.number())
                + (move.to() == ClaimStatus.SETTLED ? " due=" + (shown.due() == null ? "n/a" : shown.due()) : "")
                + (move.from() == ClaimStatus.PENDING && move.to() == ClaimStatus.OPEN ? " reason=" + input.reason() : ""));
        rollups.record(claim.getSheetId(), input.user(), before);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateStatus {
    public void validate(@RequestBody StatusRequest request, Out<StatusInput> body) throws InvalidSheetException {
        String status = request == null || request.status() == null ? "" : request.status().trim();
        ClaimStatus to;
        try {
            to = ClaimStatus.valueOf(status);
        } catch (IllegalArgumentException e) {
            throw new InvalidSheetException("Not a claim status: " + status);
        }
        boolean review = Boolean.TRUE.equals(request.review());
        String reason = request.reason() == null ? "" : request.reason().trim();
        if (review && to != ClaimStatus.SETTLED && to != ClaimStatus.OPEN) {
            throw new InvalidSheetException("A review approves or rejects a claim");
        }
        if (review && to == ClaimStatus.OPEN && reason.isEmpty()) {
            throw new InvalidSheetException("A rejection needs a reason");
        }
        body.set(new StatusInput(to, request.user(), review, reason));
    }
}
package net.officefloor.hq.app.claim;

/** A validated claim status change; {@code review} for a steward approving (SETTLED) or rejecting
 *  (OPEN, with its trimmed {@code reason}) a PENDING claim. */
public record StatusInput(ClaimStatus status, String user, boolean review, String reason) {
}
package net.officefloor.hq.app.sheet;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandleInvalidSheet {
    public void handle(@Parameter InvalidSheetException ex, ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.BAD_REQUEST));
    }
}

